from __future__ import annotations

import json
from pathlib import Path


_ALIASES_PATH = Path(__file__).with_name("region_aliases.json")


def _region_code(region):
    if not region:
        return None
    aliases = json.loads(_ALIASES_PATH.read_text(encoding="utf-8"))
    return aliases.get(region, region if len(region) == 2 else None)


def build_internal_request(params):
    internal = dict(params)
    internal["state_code"] = _region_code(internal.get("region"))
    if internal.get("sort_phrase") == "amount descending":
        internal["sort_by"] = "amount"
        internal["sort_direction"] = "desc"
    return internal


def build_api_payload(internal_request):
    """Translate the normalized internal request into the search API contract."""
    return {
        "region_code": internal_request.get("state_code"),
        "sort_by": internal_request.get("sort_by"),
        "sort_order": internal_request.get("sort_direction"),
        "start_date": internal_request.get("start_date"),
        "end_date": internal_request.get("end_date"),
    }
